head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "heatmap";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/HEATMAP/data/HEATMAP.json";             // 순수 데이터 JSON (type 없음)
scwin.CHART_CONFIG = {
  "tooltip": {   // 툴팁
    "show": false   // 표시 여부
  },
  "extend": {   // 차트별 세부 옵션
    "heatmap": {   // 히트맵 전용 옵션
      "startColor": "#FFFDEC",   // 시작 색
      "endColor": "#A3DC9A",   // 끝 색
      "useLargeAmount": true,   // 대용량 모드
      "largeJson": [],
      "xRange": {   // X 범위
        "min": 0,   // 최소값
        "max": 100   // 최대값
      },
      "yRange": {   // Y 범위
        "min": 0,   // 최소값
        "max": 1000   // 최대값
      },
      "xBandCnt": 10,   // X 밴드 수
      "yBandCnt": 10,   // Y 밴드 수
      "hoverReverse": true,
      "hoverStyle": {
        "strokeStyle": "dotted",   // 선 스타일
        "strokeColor": "red",   // 선 색
        "strokeWidth": 3,   // 선 두께
        "fillColor": "yellow",   // 채움 색
        "fillOpacity": 0.2   // 채움 투명도
      }
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "keys": {   // 데이터 필드 매핑
      "x": "xData",
      "value": [   // 값 필드
        {
          "y": "yData",
          "value": "data"   // 값 필드
        }
      ]
    }
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
